CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultAsset_AfterDelete] ON [dbo].[ResponsibilityRuleResultAsset] AFTER DELETE AS SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted D INNER JOIN [dbo].[Asset] A ON D.AssetID = A.ID WHERE D.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted D INNER JOIN [dbo].[Asset] A ON D.AssetTypeID = A.AssetTypeID WHERE D.AssetID = 0; GO
CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultAsset_AfterInsert] ON [dbo].[ResponsibilityRuleResultAsset] AFTER INSERT AS SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN [dbo].[Asset] A ON I.AssetID = A.ID WHERE I.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN [dbo].[Asset] A ON I.AssetTypeID = A.AssetTypeID WHERE I.AssetID = 0; GO
